1	import { ensureSyntaxTree, syntaxTree } from "@codemirror/language";
2	import { EditorView, type ViewUpdate } from "@codemirror/view";
3	import type DiscourseGraphPlugin from "~/index";
4	import {
5	  closeNodeSummonMenu,
6	  getActiveNodeSummonMenu,
7	  openNodeSummonMenu,
8	} from "~/components/NodeSummonMenu";
9	import { getTypedTriggerStart } from "~/utils/nodeSearchTrigger";
10	
11	// Obsidian's markdown token names where `@` is code, YAML, link text, math or a comment.
12	const NON_PROSE_TOKEN = /codeblock|inline-code|frontmatter|link|math|comment/i;
13	
14	const isInNonProse = (state: ViewUpdate["state"], pos: number): boolean => {
15	  // The background parse may not have reached the cursor yet in a long note.
16	  const tree = ensureSyntaxTree(state, pos, 50) ?? syntaxTree(state);
17	  let node = tree.resolveInner(pos, -1);
18	  while (!NON_PROSE_TOKEN.test(node.name)) {
19	    if (!node.parent) return false;
20	    node = node.parent;
21	  }
22	  return true;
23	};
24	
25	// Keeps the open menu's query in sync, or closes it once the trigger is gone.
26	const updateOpenMenu = (update: ViewUpdate): boolean => {
27	  const menu = getActiveNodeSummonMenu();
28	  if (!menu || menu.view !== update.view) return false;
29	  if (!update.docChanged && !update.selectionSet) {
30	    if (update.geometryChanged) menu.reposition();
31	    return true;
32	  }
33	
34	  const { doc, selection } = update.state;
35	  const triggerFrom = update.changes.mapPos(menu.triggerFrom);
36	  const queryFrom = triggerFrom + menu.trigger.length;
37	  const head = selection.main.head;
38	
39	  const triggerIntact =
40	    queryFrom <= doc.length &&
41	    doc.sliceString(triggerFrom, queryFrom) === menu.trigger;
42	  const cursorInQuery =
43	    selection.main.empty &&
44	    head >= queryFrom &&
45	    doc.lineAt(head).number === doc.lineAt(triggerFrom).number;
46	
47	  if (!triggerIntact || !cursorInQuery) {
48	    closeNodeSummonMenu();
49	    return true;
50	  }
51	
52	  // No node title starts with a space, so `@ the lab` is prose, not a search.
53	  const query = doc.sliceString(queryFrom, head);
54	  if (/^\s/.test(query)) {
55	    closeNodeSummonMenu();
56	    return true;
57	  }
58	
59	  menu.triggerFrom = triggerFrom;
60	  menu.setQuery(query);
61	  // Text inserted above the trigger moves it on screen.
62	  if (update.docChanged || update.geometryChanged) menu.reposition();
63	  return true;
64	};
65	
66	export const createNodeSummonExtension = (
67	  plugin: DiscourseGraphPlugin,
68	): ReturnType<typeof EditorView.updateListener.of> =>
69	  EditorView.updateListener.of((update) => {
70	    if (updateOpenMenu(update)) return;
71	
72	    // Only typing opens it; moving the cursor back into existing `@text` does not.
73	    const typed = update.transactions.some((tr) =>
74	      tr.isUserEvent("input.type"),
75	    );
76	    if (!update.docChanged || !typed) return;
77	
78	    const { doc, selection } = update.state;
79	    if (!selection.main.empty) return;
80	    const head = selection.main.head;
81	    const line = doc.lineAt(head);
82	    const trigger = plugin.settings.nodeSearchTrigger;
83	    const start = getTypedTriggerStart({
84	      lineBeforeCursor: doc.sliceString(line.from, head),
85	      trigger,
86	    });
87	    if (start === null || isInNonProse(update.state, head)) return;
88	
89	    openNodeSummonMenu({
90	      plugin,
91	      view: update.view,
92	      triggerFrom: line.from + start,
93	      trigger,
94	    });
95	  });
