1	import {
2	  rankDiscourseNodesByTitle,
3	  type RankedDiscourseNode,
4	  type SearchableNode,
5	} from "~/services/QueryEngine";
6	import type { DiscourseNode } from "~/types";
7	
8	// Matches Roam's summoning menu.
9	const MAX_NODES_PER_TYPE = 10;
10	
11	export type SummonMenuGroup = {
12	  nodeType: DiscourseNode;
13	  nodes: RankedDiscourseNode[];
14	};
15	
16	export const groupNodesForSummonMenu = ({
17	  nodes,
18	  nodeTypes,
19	  query,
20	}: {
21	  nodes: SearchableNode[];
22	  nodeTypes: DiscourseNode[];
23	  query: string;
24	}): SummonMenuGroup[] => {
25	  const ranked = rankDiscourseNodesByTitle({ candidates: nodes, query });
26	
27	  return nodeTypes
28	    .map((nodeType) => ({
29	      nodeType,
30	      nodes: ranked
31	        .filter((node) => node.nodeTypeId === nodeType.id)
32	        .slice(0, MAX_NODES_PER_TYPE),
33	    }))
34	    .filter((group) => group.nodes.length > 0);
35	};
