1	import { TFile } from "obsidian";
2	import { describe, expect, it, vi } from "vitest";
3	import type { SearchableNode } from "~/services/QueryEngine";
4	import type { DiscourseNode } from "~/types";
5	import { groupNodesForSummonMenu } from "~/utils/nodeSummonResults";
6	
7	// Stand-in scorer: earlier substring hits score higher, mirroring fuzzy search's ordering.
8	vi.mock("obsidian", async (importOriginal) => ({
9	  ...(await importOriginal<object>()),
10	  prepareFuzzySearch: (query: string) => (text: string) => {
11	    const index = text.toLowerCase().indexOf(query.toLowerCase());
12	    return index < 0
13	      ? null
14	      : { score: -index, matches: [[index, index + query.length]] };
15	  },
16	}));
17	
18	const nodeType = (id: string, name: string): DiscourseNode => ({
19	  id,
20	  name,
21	  format: `${name} - {content}`,
22	  created: 0,
23	  modified: 0,
24	});
25	
26	const CLAIM = nodeType("claim", "Claim");
27	const EVIDENCE = nodeType("evidence", "Evidence");
28	const QUESTION = nodeType("question", "Question");
29	
30	const node = (title: string, nodeTypeId: string): SearchableNode => {
31	  const file = new TFile();
32	  file.path = `${title}.md`;
33	  file.basename = title;
34	  return { file, title, nodeTypeId };
35	};
36	
37	const summarize = (
38	  groups: ReturnType<typeof groupNodesForSummonMenu>,
39	): { type: string; titles: string[] }[] =>
40	  groups.map((group) => ({
41	    type: group.nodeType.name,
42	    titles: group.nodes.map((n) => n.title),
43	  }));
44	
45	describe("groupNodesForSummonMenu", () => {
46	  it("groups nodes under their type in settings order and hides empty types", () => {
47	    const groups = groupNodesForSummonMenu({
48	      nodes: [node("Arp2/3 KO", "evidence"), node("Actin branches", "claim")],
49	      nodeTypes: [CLAIM, EVIDENCE, QUESTION],
50	      query: "",
51	    });
52	
53	    expect(summarize(groups)).toEqual([
54	      { type: "Claim", titles: ["Actin branches"] },
55	      { type: "Evidence", titles: ["Arp2/3 KO"] },
56	    ]);
57	  });
58	
59	  it("keeps only the top 10 results for each type", () => {
60	    const claims = "LKJIHGFEDCBA".split("").map((t) => node(t, "claim"));
61	
62	    const groups = groupNodesForSummonMenu({
63	      nodes: [...claims, node("Lone evidence", "evidence")],
64	      nodeTypes: [CLAIM, EVIDENCE],
65	      query: "",
66	    });
67	
68	    expect(summarize(groups)).toEqual([
69	      {
70	        type: "Claim",
71	        titles: ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J"],
72	      },
73	      { type: "Evidence", titles: ["Lone evidence"] },
74	    ]);
75	  });
76	
77	  it("narrows each type to matching titles, best match first", () => {
78	    const groups = groupNodesForSummonMenu({
79	      nodes: [
80	        node("Branched actin", "claim"),
81	        node("Actin cap", "claim"),
82	        node("Myosin pulls", "claim"),
83	        node("Myosin KO", "evidence"),
84	      ],
85	      nodeTypes: [CLAIM, EVIDENCE],
86	      query: "actin",
87	    });
88	
89	    expect(summarize(groups)).toEqual([
90	      { type: "Claim", titles: ["Actin cap", "Branched actin"] },
91	    ]);
92	  });
93	
94	  it("returns no groups when nothing matches", () => {
95	    const groups = groupNodesForSummonMenu({
96	      nodes: [node("Actin cap", "claim")],
97	      nodeTypes: [CLAIM],
98	      query: "tubulin",
99	    });
100	
101	    expect(groups).toEqual([]);
102	  });
103	});
