1	import { Platform } from "obsidian";
2	import type { KeyboardEvent } from "react";
3	
4	export type HintKey =
5	  | "Mod"
6	  | "Alt"
7	  | "Shift"
8	  | "Enter"
9	  | "Escape"
10	  | "Tab"
11	  | "ArrowLeft"
12	  | "ArrowRight";
13	
14	// Obsidian shows glyphs on macOS and spelled-out words everywhere else.
15	const MAC_SYMBOLS: Record<HintKey, string> = {
16	  Mod: "⌘",
17	  Alt: "⌥",
18	  Shift: "⇧",
19	  Enter: "↵",
20	  Escape: "esc",
21	  Tab: "⇥",
22	  ArrowLeft: "←",
23	  ArrowRight: "→",
24	};
25	
26	const NON_MAC_SYMBOLS: Record<HintKey, string> = {
27	  Mod: "Ctrl",
28	  Alt: "Alt",
29	  Shift: "Shift",
30	  Enter: "Enter",
31	  Escape: "Esc",
32	  Tab: "Tab",
33	  ArrowLeft: "←",
34	  ArrowRight: "→",
35	};
36	
37	/** Takes `isMacOS` so the non-mac branch can be checked without that platform. */
38	export const formatHintKeys = ({
39	  keys,
40	  isMacOS,
41	}: {
42	  keys: HintKey[];
43	  isMacOS: boolean;
44	}): string[] =>
45	  keys.map((key) => (isMacOS ? MAC_SYMBOLS : NON_MAC_SYMBOLS)[key]);
46	
47	export const getHintKeys = (keys: HintKey[]): string[] =>
48	  formatHintKeys({ keys, isMacOS: Platform.isMacOS });
49	
50	// Rows are divs, so Enter and Space have to be wired up the way a button gets them free.
51	export const activateOnKey = (
52	  event: KeyboardEvent<HTMLDivElement>,
53	  activate: () => void,
54	): void => {
