1	import { Fragment, useEffect, useRef, type ReactElement } from "react";
2	import { createRoot, type Root } from "react-dom/client";
3	import { editorInfoField, Scope } from "obsidian";
4	import type { EditorView } from "@codemirror/view";
5	import type DiscourseGraphPlugin from "~/index";
6	import { QueryEngine, type SearchableNode } from "~/services/QueryEngine";
7	import {
8	  groupNodesForSummonMenu,
9	  type SummonMenuGroup,
10	} from "~/utils/nodeSummonResults";
11	
12	const VIEWPORT_MARGIN = 8;
13	
14	type NodeSummonListProps = {
15	  groups: SummonMenuGroup[];
16	  activeIndex: number;
17	  onSelect: (index: number) => void;
18	  onHover: (index: number) => void;
19	};
20	
21	const NodeSummonList = ({
22	  groups,
23	  activeIndex,
24	  onSelect,
25	  onHover,
26	}: NodeSummonListProps): ReactElement => {
27	  const activeRef = useRef<HTMLDivElement | null>(null);
28	
29	  useEffect(() => {
30	    activeRef.current?.scrollIntoView({ block: "nearest" });
31	  }, [activeIndex]);
32	
33	  if (groups.length === 0) {
34	    return <div className="suggestion-empty">No matching nodes</div>;
35	  }
36	
37	  let index = 0;
38	  return (
39	    <div className="suggestion">
40	      {groups.map((group, groupIndex) => (
41	        <Fragment key={group.nodeType.id}>
42	          <div
43	            className={`text-muted flex items-center gap-2 px-3 pb-1 pt-2 text-xs font-semibold uppercase tracking-wide ${
44	              groupIndex > 0
45	                ? "border-modifier-border mt-1 border-0 border-t border-solid"
46	                : ""
47	            }`}
48	          >
49	            <span
50	              className="h-2 w-2 shrink-0 rounded-full bg-[var(--text-faint)]"
51	              style={
52	                group.nodeType.color
53	                  ? { backgroundColor: group.nodeType.color }
54	                  : undefined
55	              }
56	            />
57	            {group.nodeType.name}
58	          </div>
59	          {group.nodes.map((node) => {
60	            const itemIndex = index++;
61	            const isActive = itemIndex === activeIndex;
62	            return (
63	              <div
64	                key={node.file.path}
65	                ref={isActive ? activeRef : undefined}
66	                className={`suggestion-item pl-7 ${isActive ? "is-selected" : ""}`}
67	                onMouseMove={() => onHover(itemIndex)}
68	                onClick={() => onSelect(itemIndex)}
69	              >
70	                {node.title}
71	              </div>
72	            );
73	          })}
74	        </Fragment>
75	      ))}
76	    </div>
77	  );
78	};
79	
80	type NodeSummonMenuOptions = {
81	  plugin: DiscourseGraphPlugin;
82	  view: EditorView;
83	  triggerFrom: number;
84	  trigger: string;
85	};
86	
87	class NodeSummonMenu {
88	  readonly view: EditorView;
89	  readonly trigger: string;
90	  triggerFrom: number;
91	  private plugin: DiscourseGraphPlugin;
92	  private nodes: SearchableNode[];
93	  private query = "";
94	  private activeIndex = 0;
95	  private groups: SummonMenuGroup[] = [];
96	  private containerEl: HTMLElement;
97	  private root: Root;
98	  private scope: Scope;
99	  private resizeObserver: ResizeObserver;
100	  private cleanupListeners: (() => void)[] = [];
101	  private closed = false;
102	
103	  constructor({ plugin, view, triggerFrom, trigger }: NodeSummonMenuOptions) {
104	    this.plugin = plugin;
105	    this.view = view;
106	    this.triggerFrom = triggerFrom;
107	    this.trigger = trigger;
108	    // Loaded once per opening; typing only re-ranks.
109	    this.nodes = new QueryEngine(plugin.app).getSearchableNodes(
110	      plugin.settings.nodeTypes,
111	    );
112	
113	    const doc = view.dom.ownerDocument;
114	    this.containerEl = doc.body.createDiv({
115	      // Hidden until the first reposition places it at the cursor.
116	      cls: "suggestion-container dg-node-summon-menu invisible",
117	    });
118	    // Keeps focus in the editor for clicks anywhere in the menu, so typing still lands.
119	    this.containerEl.addEventListener("mousedown", (event) =>
120	      event.preventDefault(),
121	    );
122	    // Mounted directly so .suggestion is the flex child that scrolls inside the capped container.
123	    this.root = createRoot(this.containerEl);
124	
125	    // Parented to app.scope so unrelated hotkeys keep working while the menu is open.
126	    this.scope = new Scope(plugin.app.scope);
127	    // Returning true lets an IME composition keep its own Enter and arrow keys.
128	    this.scope.register(
129	      [],
130	      "ArrowDown",
131	      (evt) => evt.isComposing || this.move(1),
132	    );
133	    this.scope.register(
134	      [],
135	      "ArrowUp",
136	      (evt) => evt.isComposing || this.move(-1),
137	    );
138	    this.scope.register([], "Enter", (evt) => {
139	      if (evt.isComposing) return true;
140	      if (this.closeIfEditorBlurred()) return true;
141	      if (this.itemCount() === 0) {
142	        this.close();
143	        return true;
144	      }
145	      this.select(this.activeIndex);
146	      return false;
147	    });
148	    this.scope.register([], "Escape", (evt) => {
149	      if (evt.isComposing || this.closeIfEditorBlurred()) return true;
150	      this.close();
151	      return false;
152	    });
153	    plugin.app.keymap.pushScope(this.scope);
154	
155	    const closeIfOutside = (event: MouseEvent): void => {
156	      if (this.containerEl.contains(event.target as Node)) return;
157	      this.close();
158	    };
159	    doc.addEventListener("mousedown", closeIfOutside, true);
160	    this.cleanupListeners.push(() =>
161	      doc.removeEventListener("mousedown", closeIfOutside, true),
162	    );
163	
164	    // Opening another file can reuse this editor, so CodeMirror sees no typing to react to.
165	    // A late leaf change for the leaf that just opened must not close it.
166	    const { workspace } = plugin.app;
167	    const filePath = view.state.field(editorInfoField, false)?.file?.path;
168	    const workspaceRefs = [
169	      workspace.on("file-open", (file) => {
170	        if (file?.path !== filePath) this.close();
171	      }),
172	      workspace.on("active-leaf-change", (leaf) => {
173	        if (!leaf?.view.containerEl.contains(view.dom)) this.close();
174	      }),
175	    ];
176	    this.cleanupListeners.push(() =>
177	      workspaceRefs.forEach((ref) => workspace.offref(ref)),
178	    );
179	
180	    // Scrolling moves the cursor on screen without a CodeMirror update.
181	    const onScroll = (): void => this.reposition();
182	    view.scrollDOM.addEventListener("scroll", onScroll, { passive: true });
183	    this.cleanupListeners.push(() =>
184	      view.scrollDOM.removeEventListener("scroll", onScroll),
185	    );
186	
187	    // The editor's own window, so the observer also fires in popout windows.
188	    const win = doc.defaultView ?? window;
189	    this.resizeObserver = new win.ResizeObserver(() => this.reposition());
190	    this.resizeObserver.observe(this.containerEl);
191	
192	    this.regroup();
193	    this.render();
194	    this.reposition();
195	  }
196	
197	  setQuery(query: string): void {
198	    if (query === this.query) return;
199	    this.query = query;
200	    this.activeIndex = 0;
201	    this.regroup();
202	    this.render();
203	  }
204	
205	  close(): void {
206	    // A measure queued before closing can still call this.
207	    if (this.closed) return;
208	    this.closed = true;
209	    for (const cleanup of this.cleanupListeners) cleanup();
210	    this.cleanupListeners = [];
211	    this.plugin.app.keymap.popScope(this.scope);
212	    this.resizeObserver.disconnect();
213	    // Deferred: unmounting during React's event handling warns.
214	    const root = this.root;
215	    (this.view.dom.ownerDocument.defaultView ?? window).setTimeout(
216	      () => root.unmount(),
217	      0,
218	    );
219	    this.containerEl.remove();
220	    if (activeMenu === this) activeMenu = null;
221	  }
222	
223	  private itemCount(): number {
224	    return this.groups.reduce((count, group) => count + group.nodes.length, 0);
225	  }
226	
227	  // Keyboard focus can leave the editor without a mousedown; stop capturing keys then.
228	  private closeIfEditorBlurred(): boolean {
229	    if (this.view.hasFocus) return false;
230	    this.close();
231	    return true;
232	  }
233	
234	  private move(delta: number): boolean {
235	    if (this.closeIfEditorBlurred()) return true;
236	    const count = this.itemCount();
237	    // Nothing to move through, so the editor gets the arrow key.
238	    if (count === 0) return true;
239	    this.activeIndex = (this.activeIndex + delta + count) % count;
240	    this.render();
241	    return false;
242	  }
243	
244	  private select(index: number): void {
245	    const node = this.groups.flatMap((group) => group.nodes)[index];
246	    if (!node) return;
247	
248	    const sourcePath = this.view.state.field(editorInfoField, false)?.file
249	      ?.path;
250	    const link = this.plugin.app.fileManager.generateMarkdownLink(
251	      node.file,
252	      sourcePath ?? "",
253	    );
254	    const to = this.view.state.selection.main.head;
255	    const from = this.triggerFrom;
256	
257	    this.close();
258	    this.view.dispatch({
259	      changes: { from, to, insert: link },
260	      selection: { anchor: from + link.length },
261	      userEvent: "input.complete",
262	    });
263	    this.view.focus();
264	  }
265	
266	  private regroup(): void {
267	    this.groups = groupNodesForSummonMenu({
268	      nodes: this.nodes,
269	      nodeTypes: this.plugin.settings.nodeTypes,
270	      query: this.query,
271	    });
272	  }
273	
274	  private render(): void {
275	    this.root.render(
276	      <NodeSummonList
277	        groups={this.groups}
278	        activeIndex={this.activeIndex}
279	        onSelect={(index) => this.select(index)}
280	        onHover={(index) => {
281	          if (index === this.activeIndex) return;
282	          this.activeIndex = index;
283	          this.render();
284	        }}
285	      />,
286	    );
287	  }
288	
289	  // Editor layout can only be read in a measure phase, not during an update.
290	  reposition(): void {
291	    this.view.requestMeasure({
292	      read: (view) => view.coordsAtPos(this.triggerFrom),
293	      write: (coords) => {
294	        // A trigger scrolled out of view would leave the menu over unrelated text.
295	        const scroller = this.view.scrollDOM.getBoundingClientRect();
296	        if (
297	          !coords ||
298	          coords.bottom < scroller.top ||
299	          coords.top > scroller.bottom
300	        ) {
301	          this.close();
302	          return;
303	        }
304	        const win = this.view.dom.ownerDocument.defaultView ?? window;
305	        const { width, height } = this.containerEl.getBoundingClientRect();
306	        const left = Math.min(
307	          Math.max(VIEWPORT_MARGIN, coords.left),
308	          Math.max(VIEWPORT_MARGIN, win.innerWidth - width - VIEWPORT_MARGIN),
309	        );
310	        const spaceBelow = win.innerHeight - coords.bottom;
311	        const openUpward =
312	          spaceBelow < height + VIEWPORT_MARGIN && coords.top > spaceBelow;
313	        const top = openUpward
314	          ? Math.max(VIEWPORT_MARGIN, coords.top - height - 4)
315	          : coords.bottom + 4;
316	        this.containerEl.style.left = `${left}px`;
317	        this.containerEl.style.top = `${top}px`;
318	        this.containerEl.removeClass("invisible");
319	      },
320	    });
321	  }
322	}
323	
324	let activeMenu: NodeSummonMenu | null = null;
325	
326	export const getActiveNodeSummonMenu = (): NodeSummonMenu | null => activeMenu;
327	
328	export const openNodeSummonMenu = (options: NodeSummonMenuOptions): void => {
329	  activeMenu?.close();
330	  activeMenu = new NodeSummonMenu(options);
331	};
332	
333	export const closeNodeSummonMenu = (): void => {
334	  activeMenu?.close();
335	};
